85	    /**
86	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
87	     * is at capacity and cannot take any more.
88	     */
89	    private static final int CITY_CAPACITY = 50;
90	
91	    /**
92	     * The maximum number of owners that may be registered in a single day. Once this many owners
93	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
94	     * owners can be created that day.
95	     */
96	    private static final int DAILY_OWNER_LIMIT = 100;
