116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
