141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        validateRequiredFields(ownerFieldsDto);
145	        rejectDailyLimitReached();
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        String address = normalizeAddress(ownerFieldsDto.getAddress());
149	        owner.setAddress(address);
150	        rejectCityAtCapacity(owner.getCity());
151	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
152	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
153	        } else {
154	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
155	        }
156	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
157	        rejectDuplicateTelephone(telephone);
158	        owner.setTelephone(telephone);
159	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
160	        if (owner.getRegistrationDate() == null) {
161	            owner.setRegistrationDate(LocalDate.now());
162	        }
163	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
164	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
165	        this.clinicService.saveOwner(owner);
166	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
167	        headers.setLocation(UriComponentsBuilder.newInstance()
168	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
169	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
170	    }
