266	    /**
267	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
268	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
269	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
270	     *
271	     * @param ownerFieldsDto the submitted owner fields
272	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
273	     *                                     name of every offending field
274	     */
275	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
276	        List<String> missingFields = new ArrayList<>();
277	        if (isBlank(ownerFieldsDto.getFirstName())) {
278	            missingFields.add("firstName");
279	        }
280	        if (isBlank(ownerFieldsDto.getLastName())) {
281	            missingFields.add("lastName");
282	        }
283	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
284	            missingFields.add("address");
285	        }
286	        if (isBlank(ownerFieldsDto.getCity())) {
287	            missingFields.add("city");
288	        }
289	        if (isBlank(ownerFieldsDto.getTelephone())) {
290	            missingFields.add("telephone");
291	        }
292	        if (!missingFields.isEmpty()) {
293	            throw new InvalidOwnerFieldsException(missingFields);
294	        }
295	    }
296	
297	    private boolean isBlank(String value) {
298	        return value == null || value.isBlank();
299	    }
300	
301	    /**
302	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
303	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
304	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
305	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
306	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
307	     *
308	     * @param telephone the raw telephone value submitted by the client
309	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
310	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
311	     *                                     400 response
312	     */
313	    private String normalizeTelephone(String telephone) {
314	        String e164 = toE164(telephone);
315	        if (e164 == null) {
316	            throw new InvalidOwnerFieldsException(List.of("telephone"));
317	        }
318	        return e164;
319	    }
320	
321	    /**
322	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
323	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
324	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
325	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
326	     *
327	     * @param telephone the raw telephone value, possibly {@code null}
328	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
329	     */
330	    private String toE164(String telephone) {
331	        if (telephone == null) {
332	            return null;
333	        }
334	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
335	        boolean hasPlus = cleaned.startsWith("+");
336	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
337	        String nationalSignificant = hasPlus
338	            ? digits
339	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
340	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
341	            return null;
342	        }
343	        return "+" + nationalSignificant;
344	    }
345	
346	    /**
347	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
348	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
349	     * returned value is that address lower-cased.
350	     *
351	     * @param email the raw email value submitted by the client, or {@code null} if omitted
352	     * @return the lower-cased email, or {@code null} if none was supplied
353	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
354	     *                                     yielding a 400 response
355	     */
356	    private String normalizeEmail(String email) {
357	        if (email == null) {
358	            return null;
359	        }
360	        if (!EMAIL_PATTERN.matcher(email).matches()) {
361	            throw new InvalidOwnerFieldsException(List.of("email"));
362	        }
363	        return email.toLowerCase(Locale.ROOT);
364	    }
365	
366	    /**
367	     * Counts the existing owners that, before this create, already share the given first name and
368	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
369	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
370	     * been saved yet, so it is never included in the count.
371	     *
372	     * @param firstName the first name of the owner being created
373	     * @param lastName  the last name of the owner being created
374	     * @return the number of existing owners sharing both names
375	     */
376	    private int countNamesakes(String firstName, String lastName) {
377	        String normalizedFirstName = normalizeForComparison(firstName);
378	        String normalizedLastName = normalizeForComparison(lastName);
379	        return (int) this.clinicService.findAllOwners().stream()
380	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
381	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
382	            .count();
383	    }
384	
385	    /**
386	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
387	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
388	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
389	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
390	     *
391	     * @param city     the owner's city
392	     * @param lastName the owner's last name
393	     * @return the formatted customer code
394	     */
395	    private String generateCustomerCode(String city, String lastName) {
396	        String city3 = first3Letters(city);
397	        String last3 = first3Letters(lastName);
398	        int sequence = countOwnersInCity(city) + 1;
399	        return String.format("%s-%s-%04d", city3, last3, sequence);
400	    }
401	
402	    /**
403	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
404	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
405	     *
406	     * @param value the value to abbreviate
407	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
408	     */
409	    private String first3Letters(String value) {
410	        String letters = value.replaceAll("[^\\p{L}]", "");
411	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
412	    }
413	
414	    /**
415	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
416	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
417	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
418	     * has not been saved yet, so it is never included in the count.
419	     *
420	     * @param city the city of the owner being created
421	     * @return the number of existing owners in that city
422	     */
423	    private int countOwnersInCity(String city) {
424	        String normalizedCity = normalizeForComparison(city);
425	        return (int) this.clinicService.findAllOwners().stream()
426	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
427	            .count();
428	    }
429	
430	    /**
431	     * Rejects creation of an owner whose city already contains the maximum number of owners
432	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
433	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
434	     *
435	     * @param city the city of the owner being created
436	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
437	     *                                      owners, yielding a 409 Conflict response
438	     */
439	    private void rejectCityAtCapacity(String city) {
440	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
441	            throw new OwnerCityAtCapacityException(city);
442	        }
443	    }
444	
445	    /**
446	     * Rejects creation of an owner once today has already reached its daily quota of
447	     * {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
448	     * being today's date; the owner being created has not been saved yet, so it is never included
449	     * in the count.
450	     *
451	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
452	     *                                         carry today's registration date, yielding a
453	     *                                         429 Too Many Requests response
454	     */
455	    private void rejectDailyLimitReached() {
456	        LocalDate today = LocalDate.now();
457	        long createdToday = this.clinicService.findAllOwners().stream()
458	            .filter(existing -> today.equals(existing.getRegistrationDate()))
459	            .count();
460	        if (createdToday >= DAILY_OWNER_LIMIT) {
461	            throw new DailyOwnerLimitReachedException(today);
462	        }
463	    }
464	
465	    /**
466	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
467	     * telephones are converted to E.164 here as well so the comparison is independent of the format
468	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
469	     * ignored rather than matched.
470	     *
471	     * @param telephone the E.164 telephone of the owner being created
472	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
473	     *                                          yielding a 409 Conflict response
474	     */
475	    private void rejectDuplicateTelephone(String telephone) {
476	        boolean inUse = this.clinicService.findAllOwners().stream()
477	            .map(Owner::getTelephone)
478	            .map(this::toE164)
479	            .anyMatch(telephone::equals);
480	        if (inUse) {
481	            throw new DuplicateOwnerTelephoneException(telephone);
482	        }
483	    }
484	
485	    /**
486	     * Rejects creation of an owner whose last name and address both match an existing owner's,
487	     * which marks them as belonging to the same household. Both the last name and the address are
488	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
489	     * that differ only in letter case or spacing are still treated as a match.
490	     *
491	     * @param lastName the last name of the owner being created
492	     * @param address  the address of the owner being created
493	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
494	     *                                          address, yielding a 409 Conflict response
495	     */
496	    private void rejectDuplicateHousehold(String lastName, String address) {
497	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
498	            throw new DuplicateOwnerHouseholdException(lastName, address);
499	        }
500	    }
501	
502	    /**
503	     * Finds every existing owner belonging to the household identified by the given last name and
504	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
505	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
506	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
507	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
508	     * and {@link #assignHousehold}.
509	     *
510	     * @param lastName the last name of the owner being created
511	     * @param address  the address of the owner being created
512	     * @return the existing owners in that household, or an empty list if there are none
513	     */
514	    private List<Owner> findHouseholdMembers(String lastName, String address) {
515	        String normalizedLastName = normalizeForComparison(lastName);
516	        String normalizedAddress = normalizeAddress(address);
517	        return this.clinicService.findAllOwners().stream()
518	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
519	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
520	            .toList();
521	    }
522	
523	    /**
524	     * Enrolls a newly created owner into the household of any existing owner that shares its last
525	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
526	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
527	     * whitespace. When at least one such owner already exists, every member of the household — the
528	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
529	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
530	     * and address is created and back-filled onto the existing members. When no owner yet lives at
531	     * that address under the same last name no identifier is assigned and the owner is created alone.
532	     *
533	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
534	     * @param lastName the last name of the owner being created
535	     * @param address  the address of the owner being created
536	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
537	     */
538	    private String assignHousehold(Owner newOwner, String lastName, String address) {
539	        List<Owner> members = findHouseholdMembers(lastName, address);
540	        if (members.isEmpty()) {
541	            return null;
542	        }
543	        String householdId = members.stream()
544	            .map(Owner::getHouseholdId)
545	            .filter(existing -> existing != null && !existing.isBlank())
546	            .findFirst()
547	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
548	        for (Owner member : members) {
549	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
550	                member.setHouseholdId(householdId);
551	                this.clinicService.saveOwner(member);
552	            }
553	        }
554	        newOwner.setHouseholdId(householdId);
555	        return householdId;
556	    }
557	
558	    /**
559	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
560	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
561	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
562	     * same identifier, so members of one household share a single value.
563	     *
564	     * @param normalizedLastName the household's last name, already normalized for comparison
565	     * @param normalizedAddress  the household's address, already normalized for comparison
566	     * @return the derived household identifier
567	     */
568	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
569	        try {
570	            byte[] digest = MessageDigest.getInstance("SHA-256")
571	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
572	            StringBuilder hex = new StringBuilder(digest.length * 2);
573	            for (byte b : digest) {
574	                hex.append(String.format("%02x", b));
575	            }
576	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
577	        } catch (NoSuchAlgorithmException e) {
578	            throw new IllegalStateException("SHA-256 algorithm not available", e);
579	        }
580	    }
581	
582	    /**
583	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
584	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
585	     * the result is lower-cased.
586	     *
587	     * @param value the value to normalize, possibly {@code null}
588	     * @return the normalized value, or an empty string if {@code value} is {@code null}
589	     */
590	    private String normalizeForComparison(String value) {
591	        if (value == null) {
592	            return "";
593	        }
594	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
595	    }
596	
597	    /**
598	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
599	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
600	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
601	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
602	     * This normalized value is what gets stored and returned, and it is the form every address
603	     * comparison (household duplicate detection and the shared household id) uses.
604	     *
605	     * @param address the raw address value submitted by the client, possibly {@code null}
606	     * @return the normalized address, or an empty string if {@code address} is {@code null}
607	     */
608	    private String normalizeAddress(String address) {
609	        if (address == null) {
610	            return "";
611	        }
612	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
613	        if (collapsed.isEmpty()) {
614	            return collapsed;
615	        }
616	        String[] tokens = collapsed.split(" ");
617	        StringBuilder normalized = new StringBuilder(collapsed.length());
618	        for (int i = 0; i < tokens.length; i++) {
619	            if (i > 0) {
620	                normalized.append(' ');
621	            }
622	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
623	        }
624	        return normalized.toString();
625	    }
626	}
